var postgresNonTypeLiteralPrefixes = map[string]struct{}{
	"ALL": {}, "AND": {}, "AS": {}, "AT": {}, "BY": {}, "CASE": {},
	"DISTINCT": {}, "ELSE": {}, "ESCAPE": {}, "FETCH": {}, "FIRST": {},
	"FROM": {}, "HAVING": {}, "ILIKE": {}, "IN": {}, "IS": {}, "JOIN": {},
	"LAST": {}, "LIKE": {}, "LIMIT": {}, "NEXT": {}, "NOT": {}, "NULLS": {},
	"OFFSET": {}, "ON": {}, "OR": {}, "ORDER": {}, "RETURNING": {},
	"SELECT": {}, "SIMILAR": {}, "THEN": {}, "VALUES": {}, "WHEN": {},
	"WHERE": {},
}

// postgresTypeLiteralViolation recognizes PostgreSQL's type 'string' constant
// syntax. Unlike CAST/::, this syntax invokes the type input routine directly;
// explicit or user-defined types must therefore be rejected before parsing on
// the target database.
func postgresTypeLiteralViolation(sql string, literalStart int) string {
	if literalStart <= 0 || literalStart > len(sql) {
		return "PostgreSQL 문자열 상수 형식을 안전하게 분류하지 못했습니다."
	}
	originalEnd := literalStart
	end := skipSQLTriviaBackward(sql, originalEnd)
	direct := end == originalEnd
	for end > 0 && sql[end-1] == ']' {
		left := matchingDelimiterBackward(sql, end, '[', ']')
		if left < 0 {
			return "PostgreSQL 문자열 상수 형식을 안전하게 분류하지 못했습니다."
		}
		end = skipSQLTriviaBackward(sql, left)
	}
	if end > 0 && sql[end-1] == ')' {
		left := matchingDelimiterBackward(sql, end, '(', ')')
		if left < 0 {
			return "PostgreSQL 문자열 상수 형식을 안전하게 분류하지 못했습니다."
		}
		end = skipSQLTriviaBackward(sql, left)
	}
	name, start, quoted, ok := postgresIdentifierBackward(sql, end)
	if !ok {
		return ""
	}
	upperName := strings.ToUpper(name)
	if direct && !quoted {
		switch upperName {
		case "E", "B", "X", "N":
			// PostgreSQL lexical string/bit prefixes, not type names.
			return ""
		}
	}
	before := skipSQLTriviaBackward(sql, start)
	qualified := before > 0 && sql[before-1] == '.'
	if quoted || qualified {
		return fmt.Sprintf("PostgreSQL의 비허용 사용자 정의 문자열 상수 형식 %s이 포함되어 있습니다.", boundedToken(name, 96))
	}
	if _, grammar := postgresNonTypeLiteralPrefixes[upperName]; grammar {
		return ""
	}
	if _, builtin := postgresBuiltinCastTypes[upperName]; builtin || postgresBuiltinMultiwordTypeBefore(sql, start, upperName) {
		return ""
	}
	return fmt.Sprintf("PostgreSQL의 비허용 사용자 정의 문자열 상수 형식 %s이 포함되어 있습니다.", boundedToken(name, 96))
}

func postgresBuiltinMultiwordTypeBefore(sql string, start int, last string) bool {
	words := []string{last}
	cursor := start
	typmodSkipped := false
	for len(words) < 5 {
		cursor = skipSQLTriviaBackward(sql, cursor)
		if !typmodSkipped && cursor > 0 && sql[cursor-1] == ')' {
			left := matchingDelimiterBackward(sql, cursor, '(', ')')
			if left < 0 {
				return false
			}
			cursor = skipSQLTriviaBackward(sql, left)
			typmodSkipped = true
		}
		name, next, quoted, ok := postgresIdentifierBackward(sql, cursor)
		if !ok || quoted {
			break
		}
		words = append([]string{strings.ToUpper(name)}, words...)
		cursor = next
	}
	joined := strings.Join(words, " ")
	for _, suffix := range []string{
		"DOUBLE PRECISION", "CHARACTER VARYING", "BIT VARYING",
		"TIME WITH TIME ZONE", "TIME WITHOUT TIME ZONE",
		"TIMESTAMP WITH TIME ZONE", "TIMESTAMP WITHOUT TIME ZONE",
	} {
		if strings.HasSuffix(joined, suffix) {
			return true
		}
	}
	return false
}

func skipSQLTriviaBackward(value string, end int) int {
	for end > 0 {
		changed := false
		for end > 0 {
			r, size := utf8.DecodeLastRuneInString(value[:end])
			if !unicode.IsSpace(r) {
				break
			}
			newline := r == '\n' || r == '\r'
			newlineAt := end - size
			end -= size
			changed = true
			if newline {
				lineStart := strings.LastIndexByte(value[:newlineAt], '\n') + 1
				if marker := strings.LastIndex(value[lineStart:newlineAt], "--"); marker >= 0 {
					end = lineStart + marker
					break
				}
			}
		}
		if end >= 2 && value[end-2:end] == "*/" {
			start, ok := matchingBlockCommentBackward(value, end)
			if !ok {
				return end
			}
			end = start
			changed = true
			continue
		}
		if !changed {
			break
		}
	}
	return end
}

func matchingBlockCommentBackward(value string, end int) (int, bool) {
	if end < 2 || value[end-2:end] != "*/" {
		return end, false
	}
	depth := 1
	for cursor := end - 3; cursor >= 0; cursor-- {
		if cursor > 0 && value[cursor-1:cursor+1] == "*/" {
			depth++
			cursor--
			continue
		}
		if cursor > 0 && value[cursor-1:cursor+1] == "/*" {
			depth--
			if depth == 0 {
				return cursor - 1, true
			}
			cursor--
		}
	}
	return end, false
}

func matchingDelimiterBackward(value string, end int, left, right byte) int {
	depth := 0
	for index := end - 1; index >= 0; index-- {
		switch value[index] {
		case right:
			depth++
		case left:
			depth--
			if depth == 0 {
				return index
			}
		}
	}
	return -1
}

func postgresIdentifierBackward(value string, end int) (string, int, bool, bool) {
	end = skipSQLTriviaBackward(value, end)
	if end <= 0 {
		return "", end, false, false
	}
	if value[end-1] == '"' {
		for start := end - 2; start >= 0; start-- {
			if value[start] != '"' {
				continue
			}
			if next, found := quotedEnd(value, start, '"'); found && next == end {
				name := strings.ReplaceAll(value[start+1:end-1], `""`, `"`)
				return name, start, true, name != ""
			}
		}
		return "", end, true, false
	}
	start := end
	for start > 0 {
		r, size := utf8.DecodeLastRuneInString(value[:start])
		if !isOracleIdentifierRune(r, true) {
			break
		}
		start -= size
	}
	if start == end {
		return "", end, false, false
	}
	first, _ := utf8.DecodeRuneInString(value[start:end])
	if !isOracleIdentifierRune(first, false) {
		return "", end, false, false
	}
	return value[start:end], start, false, true
}

// postgresCallAdjacent reports whether an identifier is the callee of the
// parenthesis that follows it. The policy scanner drops operators entirely, so
// `version=(SELECT ...)` and `version(...)` leave the same word/left-paren token
// pair behind; only the source text between them tells them apart. A real call
// admits nothing but trivia — whitespace, line comments and block comments —
// between the name and its opening parenthesis, so anything else means the word
// is an operator's left operand rather than a function being called.
//
// Every uncertainty fails closed (returns true, keeping the allowlist check) so
// that a position the scanner did not record can never exempt a call.
func postgresCallAdjacent(sql string, nameToken, parenToken oraclePolicyToken) bool {
	cursor := int(nameToken.start) + len(nameToken.value)
	limit := int(parenToken.start)
	if nameToken.start < 0 || parenToken.start < 0 || cursor > limit || limit >= len(sql) {
		return true
	}
	for cursor < limit {
		switch {
		case unicode.IsSpace(rune(sql[cursor])):
			cursor++
		case cursor+1 < limit && sql[cursor:cursor+2] == "--":
			cursor += 2
			for cursor < limit && sql[cursor] != '\n' {
				cursor++
			}
		case cursor+1 < limit && sql[cursor:cursor+2] == "/*":
			next, found := flatBlockCommentEnd(sql, cursor)
			if !found || next > limit {
				return true
			}
			cursor = next
		default:
			return false
		}
	}
	return cursor == limit
}

func postgresAliasColumnList(index *postgresTokenIndex, nameIndex int) bool {
	tokens := index.tokens
	if nameIndex <= 0 {
		return false
	}
	previous := tokens[nameIndex-1]
	// A closing parenthesis precedes both `FROM (relation) alias(column,...)` and
	// an operator expression such as `(1) || fn(argument)`, so the shape alone
	// cannot exempt the call. Only a FROM item is an alias column list.
	if previous.kind == oraclePolicyRightParen && index.fromItemContext(nameIndex-1) {
		return true
	}
	// WITH ORDINALITY sits between a set-returning function and its optional
	// alias. Require the complete suffix and the same FROM context as above;
	// an identifier named ordinality must not exempt a following function call.
	if nameIndex >= 3 && previous.kind == oraclePolicyWord && !previous.quoted && strings.EqualFold(previous.value, "ORDINALITY") &&
		tokens[nameIndex-2].kind == oraclePolicyWord && !tokens[nameIndex-2].quoted && strings.EqualFold(tokens[nameIndex-2].value, "WITH") &&
		tokens[nameIndex-3].kind == oraclePolicyRightParen && index.fromItemContext(nameIndex-3) {
		return true
	}
	if previous.kind == oraclePolicyWord && !previous.quoted && strings.EqualFold(previous.value, "AS") {
		return true
	}
	if postgresCTEColumnList(index, nameIndex) {
		return true
	}
	// A qualified name precedes both `schema.relation alias(column,...)` without
	// the optional AS keyword and an operator expression such as `a.b = fn(arg)`,
	// so the shape alone cannot exempt the call. Only a FROM item is an alias
	// column list.
	return nameIndex >= 3 && previous.kind == oraclePolicyWord &&
		tokens[nameIndex-2].kind == oraclePolicyDot && tokens[nameIndex-3].kind == oraclePolicyWord &&
		index.fromItemContext(nameIndex-1)
}

// Reaching one of these words while searching left for a FROM item means the
// closing parenthesis belonged to a value expression. Keep the list broad: a
// word that is absent only widens the search, and exhausting the stream without
// finding FROM/JOIN/LATERAL already fails closed. Words that an earlier FROM
// item can legitimately carry (`ON`, `USING`, `AS` and whatever a join condition
// contains) only stop the search until a top-level comma has been crossed; see
// postgresClauseBoundaryKeywords.
var postgresValueExpressionKeywords = map[string]struct{}{
	"AND": {}, "ANY": {}, "ARRAY": {}, "AS": {}, "ASC": {}, "BETWEEN": {},
	"BY": {}, "CASE": {}, "CAST": {}, "COLLATE": {}, "DESC": {}, "DISTINCT": {},
	"ELSE": {}, "END": {}, "ESCAPE": {}, "EXCEPT": {}, "EXISTS": {},
	"FETCH": {}, "FILTER": {}, "FIRST": {}, "GROUP": {}, "HAVING": {},
	"ILIKE": {}, "IN": {}, "INTERSECT": {}, "IS": {}, "LAST": {}, "LIKE": {},
	"LIMIT": {}, "NOT": {}, "NULLS": {}, "OFFSET": {}, "ON": {}, "OR": {},
	"ORDER": {}, "OVER": {}, "PARTITION": {}, "RETURNING": {}, "ROW": {},
	"SELECT": {}, "SET": {}, "SIMILAR": {}, "SOME": {}, "TABLESAMPLE": {},
	"THEN": {}, "UNION": {}, "USING": {}, "VALUES": {}, "WHEN": {},
	"WHERE": {}, "WINDOW": {}, "WITHIN": {},
