func TestPostgresReadOnlyPagingAndCancellation(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	manager := New(nil)
	defer manager.Close()
	config := integrationConnection(t)
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatalf("Qurio integration PostgreSQL setup failed: %v", err)
	}
	result, err := manager.Execute(ctx, config.ID, "SELECT i, '행-' || i::text AS label FROM generate_series(1,5) AS t(i) ORDER BY i", 2, 2)
	if err != nil {
		t.Fatal(err)
	}
	if result.RowCount != 2 || !result.HasNext || len(result.Columns) != 2 || result.Rows[0][1] != "행-3" {
		t.Fatalf("unexpected page: %#v", result)
	}
	if _, err := manager.Execute(ctx, config.ID, "DELETE FROM users", 1, 10); err == nil {
		t.Fatal("mutation reached database")
	}
	operatorResult, err := manager.Execute(ctx, config.ID, `SELECT '{"allowed":true}'::jsonb @> '{"allowed":true}'::jsonb AS contained`, 1, 1)
