func TestPostgresOrdinalityAliasValidationAndPaging(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	manager := New(nil)
	defer manager.Close()
	config := integrationConnection(t)
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatalf("Qurio integration PostgreSQL setup failed: %v", err)
	}
	for _, from := range []string{
		`unnest(ARRAY[11,22,33]) WITH ORDINALITY g(value,position)`,
		`unnest(ARRAY[11,22,33]) WITH ORDINALITY AS g(value,position)`,
		`unnest(ARRAY[11,22,33]) with /* count */ ordinality "g"("value","position")`,
		`(VALUES (1)) AS a(n), LATERAL unnest(ARRAY[11,22,33]) WITH ORDINALITY g(value,position)`,
		`(VALUES (1)) AS a(n) JOIN unnest(ARRAY[11,22,33]) WITH ORDINALITY g(value,position) ON a.n=1`,
		`(VALUES (1)) AS a(n) JOIN (VALUES (1)) AS b(n) ON a.n=b.n, unnest(ARRAY[11,22,33]) WITH ORDINALITY g(value,position)`,
	} {
		t.Run(from, func(t *testing.T) {
			query := `SELECT g.value::text AS value, g.position::text AS position FROM ` + from + ` ORDER BY g.position`
			validation, err := manager.Validate(ctx, config.ID, query)
			if err != nil || !validation.Valid {
				t.Errorf("WITH ORDINALITY validation failed: %+v, %v", validation, err)
			}
			result, err := manager.Execute(ctx, config.ID, query, 2, 1)
			if err != nil {
				t.Fatalf("WITH ORDINALITY execution failed: %v", err)
			}
			if result.RowCount != 1 || !result.HasNext || len(result.Columns) != 2 || result.Columns[0].Name != "value" || result.Columns[1].Name != "position" || result.Rows[0][0] != "22" || result.Rows[0][1] != "2" {
				t.Fatalf("unexpected WITH ORDINALITY page: %#v", result)
			}
		})
	}
}

