func (m *Manager) Execute(ctx context.Context, id, statement string, page, limit int) (Result, error) {
	analysis, err := sqlsafe.RequireReadOnly(statement)
	if err != nil {
		return Result{}, err
	}
	m.mu.RLock()
	current, ok := m.entries[id]
	if !ok {
		m.mu.RUnlock()
		return Result{}, ErrNotFound
	}
	db, config := current.db, cloneConnection(current.config)
	m.mu.RUnlock()
	// Re-run the statement gate with the resolved dialect. In particular, an
	// Oracle SELECT may not use DB links or invoke arbitrary stored functions.
	// boundedQuery repeats this check at the final query construction boundary.
	analysis, err = analyzeExecutionPolicy(config, statement)
	if err != nil {
		return Result{}, err
	}
	if page == 0 {
		page = 1
	}
	limit, err = resolveRowLimit(limit, configuredMaxRows(config))
	if err != nil {
		return Result{}, err
