	queryCtx, cancel := context.WithTimeout(ctx, config.Timeout)
	defer cancel()
	started := time.Now()
	var tx *sql.Tx
	if config.Dialect == Postgres {
		tx, err = db.BeginTx(queryCtx, &sql.TxOptions{Isolation: sql.LevelRepeatableRead, ReadOnly: true})
		if err != nil {
			return Result{}, publicQueryError(err)
