func TestAnalyzeDialectAllowsPostgresOrdinalityAliasColumnLists(t *testing.T) {
	t.Parallel()
	for _, query := range []string{
		`SELECT * FROM unnest(ARRAY[11,22]) WITH ORDINALITY g(value,position)`,
		`SELECT * FROM generate_series(11,22) with ordinality g(value,position)`,
		`SELECT * FROM unnest(ARRAY[11,22]) WITH ORDINALITY AS g(value,position)`,
		`SELECT * FROM unnest(ARRAY[11,22]) WITH ORDINALITY "g"("value","position")`,
		`SELECT * FROM unnest(ARRAY[11,22]) /* rows */ WITH /* count */ ORDINALITY /* alias */ g(value,position)`,
		`SELECT * FROM (VALUES (1)) AS a(n), LATERAL unnest(ARRAY[11,22]) WITH ORDINALITY g(value,position)`,
		`SELECT * FROM (VALUES (1)) AS a(n) JOIN unnest(ARRAY[11,22]) WITH ORDINALITY g(value,position) ON a.n=g.position`,
		`SELECT * FROM (VALUES (1)) AS a(n) JOIN (VALUES (1)) AS b(n) ON a.n=b.n, unnest(ARRAY[11,22]) WITH ORDINALITY g(value,position)`,
	} {
		t.Run(query, func(t *testing.T) {
			analysis := AnalyzeDialect(query, "postgres")
			if !analysis.ReadOnly || analysis.Risk != RiskLow {
				t.Fatalf("PostgreSQL WITH ORDINALITY alias was rejected: %#v", analysis)
			}
			if _, err := RequireReadOnlyDialect(query, "postgres"); err != nil {
				t.Fatal(err)
			}
			if _, err := ApplyRowLimit(query, "postgres", 1); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestAnalyzeDialectOrdinalityDoesNotExemptFunctionCalls(t *testing.T) {
	t.Parallel()
	for _, query := range []string{
		`SELECT * FROM custom_reporting_fn(1) WITH ORDINALITY g(value,position)`,
		`SELECT * FROM unnest(ARRAY[custom_reporting_fn(1)]) WITH ORDINALITY g(value,position)`,
		`SELECT * FROM unnest(ARRAY[1]) WITH ORDINALITY g(value,position) WHERE g.value=custom_reporting_fn(1)`,
		`SELECT * FROM unnest(ARRAY[1]) WITH ORDINALITY g(value,position) JOIN (VALUES (1)) a(n) ON (g.value)=custom_reporting_fn(a.n)`,
		`SELECT ordinality + custom_reporting_fn(1) FROM public.events`,
		// Similar token sequences outside a FROM item, or with quoted keywords,
		// must not acquire an alias exemption, even for invalid SQL.
		`SELECT (1) WITH ORDINALITY custom_reporting_fn(1)`,
		`SELECT * FROM unnest(ARRAY[1]) "WITH" ORDINALITY custom_reporting_fn(1)`,
		`SELECT * FROM unnest(ARRAY[1]) WITH "ORDINALITY" custom_reporting_fn(1)`,
	} {
		t.Run(query, func(t *testing.T) {
			analysis := AnalyzeDialect(query, "postgres")
			if analysis.ReadOnly || analysis.Risk != RiskBlocked || !strings.Contains(strings.Join(analysis.Reasons, " "), "custom_reporting_fn") {
				t.Fatalf("non-allowlisted call must remain blocked: %#v", analysis)
			}
			if _, err := RequireReadOnlyDialect(query, "postgres"); err == nil {
				t.Fatal("non-allowlisted call passed the execution gate")
			}
		})
	}
}

